__NUXT_JSONP__("/ar/about", (function(a){return {data:[{details:{slug:"ar",pageTitle:"ما هو معهد منتور؟ | Mentor Language Institute",pageDescription:"معهد مينتور اللغة تأسست في عام 2002 ويقع في",section1:{title:"ما هو معهد منتور؟",description:["معهد مينتور اللغة تأسست في عام 2002 ويقع في\u003Cbr \u002F\u003Eاثنين من المناطق الشعبية: ويستوود وهوليوود.\u003Cbr \u002F\u003Eنحن نساعد الطلاب من جميع أنحاء العالم لتحسين لغتهم الإنجليزية."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"ادفع أقل لي كورسات عالية الجودة",description:["نحن نقدر أمرين: \"جودة التعليم\" و \"السعر\".","اللغة الإنجليزية هي اللغة العالمية وأداة ضرورية للتواصل مع الناس من جميع أنحاء العالم. ونأمل أن يكتسب الطلاب الدوليون مهارات اللغة الإنجليزية للنجاح في العالم. لهذا السبب، نركز في مينتور على جودة التعليم برسوم دراسية جيدة"]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"واعتبارا من عام 2020، أكثر من 17،000 طالب وتخرجوا من معهد منتور.",description:["نحن نقدم ESL (برنامج اللغة الإنجليزية العامة مع 6 المهارات: (النحوي \u002F الكتابة، القراءة \u002F المفردات، والاستماع \u002F يتحدث)، TOEFL®، إيلتس ™ (للطلاب الذين يرغبون في النقل إلى الكلية)و تويك ®.","وقد ذهب العديد من الطلاب أيضا للدراسة في الجامعات أو الكليات في الولايات المتحدة مثل جامعة UCLA ، جامعة USC وكلية سانتا مونيكا."],lists:[{link:"\u002Far\u002Ffeature",image:a,text:" 5 أسباب الناس اختيار معهد منتور"},{link:"\u002Far\u002Fcompany",image:a,text:" معلومات الشركة"},{link:"\u002Far\u002Fimage-gallery",image:a,text:" معرض الصور \u002F الفيديو"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Far",extension:".json",createdAt:"2026-10-22T16:31:28.432Z",updatedAt:"2025-05-26T12:06:27.571Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));